// ── Parse each DBS iBanking email ────────────────────────────────────────
const BIG_THRESHOLD = 25;

const results = [];

for (const item of $input.all()) {
  const body = item.json.text || item.json.snippet || '';
  const subject = item.json.subject || '';
  const fullText = subject + ' ' + body;

  // Amount: SGD 120.50 or S$120.50
  const amountMatch = fullText.match(/(?:SGD|S\$)\s*([\d,]+\.\d{2})/i);
  if (!amountMatch) continue;
  const amount = parseFloat(amountMatch[1].replace(/,/g, ''));

  // Payee
  const payeeMatch = fullText.match(
    /(?:paid?\s+to|payment(?:\s+was)?\s+made\s+to|transferred?\s+to|credited?\s+to)\s+([^\n,\.]+)/i
  );
  const payee = payeeMatch ? payeeMatch[1].trim() : 'Unknown';

  // Date — prefer body date, fall back to email date header
  const months = 'Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec';
  const dateMatch = fullText.match(new RegExp(`(\\d{1,2}\\s+(?:${months})\\s+\\d{4})`, 'i'));
  let txDate;
  if (dateMatch) {
    txDate = new Date(dateMatch[1]);
  } else {
    txDate = new Date(item.json.date);
  }
  const dateStr = txDate.toISOString().slice(0, 10);

  // Time
  const timeMatch = fullText.match(/(\d{1,2}:\d{2}(?::\d{2})?(?:\s*[AP]M)?)/i);
  const timeStr = timeMatch
    ? timeMatch[1].trim()
    : txDate.toTimeString().slice(0, 5);

  // Direction
  const isIncoming = /\b(credit|received|deposit)\b/i.test(fullText);
  const direction = isIncoming ? 'in' : 'out';

  results.push({
    json: {
      date: dateStr,
      time: timeStr,
      amount,
      payee,
      direction
    }
  });
}

if (results.length === 0) {
  // Pass a sentinel so downstream nodes still run and write an empty report
  results.push({ json: { _empty: true, date: new Date().toISOString().slice(0, 10) } });
}

return results;

// ── Aggregate all parsed transactions ────────────────────────────────────
const BIG_THRESHOLD = 25;

const allItems = $input.all();

// Filter out the empty sentinel
const transactions = allItems.filter(i => !i.json._empty);

if (transactions.length === 0) {
  return [{ json: { detailRows: [], summaryRows: [], runDate: new Date().toISOString().slice(0, 10), empty: true } }];
}

const payeeTotals = {};
const detailRows = [];

for (const item of transactions) {
  const { date, time, amount, payee, direction } = item.json;

  const bigIn  = direction === 'in'  && amount > BIG_THRESHOLD ? amount : '';
  const bigOut = direction === 'out' && amount > BIG_THRESHOLD ? amount : '';

  detailRows.push([date, time, amount, payee, bigIn, bigOut]);

  if (!payeeTotals[payee]) payeeTotals[payee] = { in: 0, out: 0 };
  payeeTotals[payee][direction] += amount;
}

const summaryRows = Object.entries(payeeTotals)
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([payee, t]) => [payee, Math.round(t.in * 100) / 100, Math.round(t.out * 100) / 100]);

const runDate = new Date().toISOString().slice(0, 10);

return [{ json: { detailRows, summaryRows, runDate, empty: false } }];

// Flatten detailRows into individual items for the Sheets append node
const { detailRows, runDate } = $input.first().json;

if (!detailRows || detailRows.length === 0) {
  return [{ json: { _sheetTab: runDate, _row: ['No transactions today', '', '', '', '', ''] } }];
}

return detailRows.map(row => ({
  json: {
    _sheetTab: runDate,
    Date:    row[0],
    Time:    row[1],
    Amount:  row[2],
    Payee:   row[3],
    'Big In':  row[4],
    'Big Out': row[5]
  }
}));

// Flatten summaryRows into individual items for the master_payee_list sheet
const { summaryRows } = $input.first().json;

if (!summaryRows || summaryRows.length === 0) {
  return [{ json: { Payee: '', 'Total In': 0, 'Total Out': 0 } }];
}

return summaryRows.map(row => ({
  json: {
    Payee:       row[0],
    'Total In':  row[1],
    'Total Out': row[2]
  }
}));
